#include <iostream>
#include <fstream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    ofstream out("nums.txt");
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        out << x << endl;
    }
    out.close();

    ifstream in("nums.txt");
    int x = 0;
    int total = 0;
    while (in >> x) {
        cout << x << endl;
        total = total + x;
    }
    cout << "一共 " << total << " {unit}" << endl;
    return 0;
}
